import subprocess,json
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
h={h['id']:h for h in r['context']['history']}
ids=['baseline-static','r0001-ordinary_pool','r0001-count_corrected_pool','r0001-ordinary_din','r0001-count_corrected_din']
print('SLICE COMPARISON: AUC, Logloss; counts from first trial')
for s in h[ids[0]]['validation']['slices']:
 first=h[ids[0]]['validation']['slices'][s]
 row={'slice':s,'samples':first['samples'],'positives':first['positives'],'negatives':first['negatives']}
 for i in ids: row[i]={k:h[i]['validation']['slices'][s][k] for k in ['auc','logloss']}
 for branch in ['pool','din']:
  a=h['r0001-ordinary_'+branch]['validation']['slices'][s]
  b=h['r0001-count_corrected_'+branch]['validation']['slices'][s]
  row['correction_delta_'+branch]={k:b[k]-a[k] for k in ['auc','logloss']}
 print(json.dumps(row))
p0,p1,d0,d1=[h[i]['validation'] for i in ids[1:]]
print('CONTRASTS', json.dumps({k:{'correction_pool':p1[k]-p0[k],'correction_din':d1[k]-d0[k],'attention_ordinary':d0[k]-p0[k],'attention_corrected':d1[k]-p1[k],'interaction':(d1[k]-d0[k])-(p1[k]-p0[k])} for k in ['auc','logloss']}))
print('COST',sum(x['wall_seconds'] for x in h.values()),sum(x['wall_seconds'] for x in h.values() if x['id'].startswith('r0001')))
PY"

